1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    font: 16px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
12	    background: #f5f5f4;
13	    color: #1c1917;
14	  }
15	  main {
16	    max-width: 32rem;
17	    margin: 3rem auto;
18	    padding: 0 1rem;
19	  }
20	  h1 { font-size: 1.5rem; margin: 0 0 1rem; }
21	  form { display: flex; flex-wrap: wrap; gap: 0.5rem; }
22	  input[type="text"] { flex: 1 1 12rem; }
23	  input[type="text"], input[type="date"] {
24	    min-width: 0;
25	    padding: 0.6rem 0.75rem;
26	    font: inherit;
27	    border: 1px solid #d6d3d1;
28	    border-radius: 6px;
29	    background: #fff;
30	  }
31	  input[type="date"] { color: #57534e; }
32	  input[type="text"]:focus, input[type="date"]:focus { outline: 2px solid #2563eb; outline-offset: -1px; border-color: transparent; }
33	  button {
34	    font: inherit;
35	    padding: 0.6rem 1rem;
36	    border: 0;
37	    border-radius: 6px;
38	    cursor: pointer;
39	  }
40	  .add { background: #2563eb; color: #fff; }
41	  .add:hover { background: #1d4ed8; }
42	  ul { list-style: none; margin: 1.25rem 0 0; padding: 0; }
43	  li {
44	    display: flex;
45	    align-items: center;
46	    gap: 0.75rem;
47	    padding: 0.6rem 0.75rem;
48	    background: #fff;
49	    border: 1px solid #e7e5e4;
50	    border-radius: 6px;
51	    margin-bottom: 0.5rem;
52	  }
53	  .text { flex: 1; overflow-wrap: anywhere; }
54	  .delete { background: transparent; color: #b91c1c; padding: 0.3rem 0.6rem; }
55	  .delete:hover { background: #fee2e2; }
56	  .empty { color: #78716c; margin-top: 1.25rem; }
57	  .filters { display: flex; gap: 0.25rem; margin-top: 1rem; }
58	  .filters button { background: transparent; color: #57534e; padding: 0.3rem 0.75rem; }
59	  .filters button:hover { background: #e7e5e4; }
60	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; }
61	  .toggle { width: 1.1rem; height: 1.1rem; margin: 0; flex: none; cursor: pointer; accent-color: #2563eb; }
62	  li[data-completed="true"] .text { color: #a8a29e; text-decoration: line-through; }
63	  .due { flex: none; font-size: 0.85rem; color: #78716c; white-space: nowrap; }
64	  li[data-overdue="true"] { border-color: #fca5a5; background: #fef2f2; box-shadow: inset 3px 0 0 #dc2626; }
65	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
66	</style>
67	</head>
68	<body>
69	<main>
70	  <h1>Todos</h1>
71	  <form id="todo-form" autocomplete="off">
72	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo">
73	    <input data-testid="todo-due" type="date" aria-label="Due date (optional)">
74	    <button data-testid="todo-add" class="add" type="submit">Add</button>
75	  </form>
76	  <div class="filters" role="group" aria-label="Filter todos">
77	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
78	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
79	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
80	  </div>
81	  <ul data-testid="todo-list"></ul>
82	  <p class="empty" hidden>No todos yet.</p>
83	</main>
84	<script>
85	(function () {
86	  var STORAGE_KEY = 'todos';
87	  var form = document.getElementById('todo-form');
88	  var input = document.querySelector('[data-testid="todo-input"]');
89	  var dueInput = document.querySelector('[data-testid="todo-due"]');
90	  var list = document.querySelector('[data-testid="todo-list"]');
91	  var empty = document.querySelector('.empty');
92	  var filterButtons = document.querySelectorAll('[data-filter]');
93	  var filter = 'all';
94	
95	  function load() {
96	    try {
97	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
98	      if (!Array.isArray(data)) return [];
99	      return data.filter(function (t) {
100	        return t && typeof t.id === 'string' && typeof t.text === 'string';
101	      }).map(function (t) {
102	        t.completed = t.completed === true;
103	        t.due = isDateString(t.due) ? t.due : null;
104	        return t;
105	      });
106	    } catch (e) {
107	      return [];
108	    }
109	  }
110	
111	  function save() {
112	    try {
113	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
114	    } catch (e) {
115	      // Storage unavailable or full; keep working in memory.
116	    }
117	  }
118	
119	  function makeId() {
120	    if (window.crypto && typeof crypto.randomUUID === 'function') {
121	      try { return crypto.randomUUID(); } catch (e) { /* fall through */ }
122	    }
123	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
124	  }
125	
126	  // Due date rule (project decision): `due` is a plain 'YYYY-MM-DD' string
127	  // holding a LOCAL calendar date, or null. Never parse it with `new Date(str)`
128	  // (that reads it as UTC midnight). Overdue means due < today's local date,
129	  // compared as strings; a todo due today is never overdue.
130	  function isDateString(value) {
131	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value);
132	  }
133	
134	  function pad(n) {
135	    return (n < 10 ? '0' : '') + n;
136	  }
137	
138	  function todayLocal() {
139	    var d = new Date();
140	    return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate());
141	  }
142	
143	  function isOverdue(todo, today) {
144	    return todo.due !== null && todo.due < today;
145	  }
146	
147	  function formatDue(due) {
148	    var parts = due.split('-');
149	    var local = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
150	    return local.toLocaleDateString(undefined, { year: 'numeric', month: 'short', day: 'numeric' });
151	  }
152	
153	  // Ordering rule (project decision): completed todos always sit below all
154	  // active todos; each group keeps insertion order, oldest first. `todos` is
155	  // stored in insertion order, so this is a stable partition.
156	  function ordered() {
157	    var active = todos.filter(function (t) { return !t.completed; });
158	    var done = todos.filter(function (t) { return t.completed; });
159	    return active.concat(done);
160	  }
161	
162	  function visible(todo) {
163	    if (filter === 'active') return !todo.completed;
164	    if (filter === 'completed') return todo.completed;
165	    return true;
166	  }
167	
168	  function render() {
169	    list.textContent = '';
170	    var shown = ordered().filter(visible);
171	    var today = todayLocal();
172	    renderedDay = today;
173	    shown.forEach(function (todo) {
174	      var li = document.createElement('li');
175	      li.setAttribute('data-testid', 'todo-item');
176	      li.setAttribute('data-id', todo.id);
177	      li.setAttribute('data-completed', todo.completed ? 'true' : 'false');
178	      li.setAttribute('data-overdue', isOverdue(todo, today) ? 'true' : 'false');
179	
180	      var box = document.createElement('input');
181	      box.type = 'checkbox';
182	      box.className = 'toggle';
183	      box.setAttribute('data-testid', 'todo-toggle');
184	      box.setAttribute('aria-label', 'Mark "' + todo.text + '" complete');
185	      box.checked = todo.completed;
186	      box.addEventListener('change', function () { toggle(todo.id); });
187	
188	      var span = document.createElement('span');
189	      span.className = 'text';
190	      span.setAttribute('data-testid', 'todo-text');
191	      span.textContent = todo.text;
192	
193	      var del = document.createElement('button');
194	      del.type = 'button';
195	      del.className = 'delete';
196	      del.setAttribute('data-testid', 'todo-delete');
197	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
198	      del.textContent = 'Delete';
199	      del.addEventListener('click', function () { remove(todo.id); });
200	
201	      li.appendChild(box);
202	      li.appendChild(span);
203	      if (todo.due) {
204	        var due = document.createElement('time');
205	        due.className = 'due';
206	        due.setAttribute('data-testid', 'todo-due-date');
207	        due.setAttribute('datetime', todo.due);
208	        due.textContent = (isOverdue(todo, today) ? 'Overdue: ' : 'Due ') + formatDue(todo.due);
209	        li.appendChild(due);
210	      }
211	      li.appendChild(del);
212	      list.appendChild(li);
213	    });
214	    if (todos.length === 0) {
215	      empty.textContent = 'No todos yet.';
216	    } else if (filter === 'active') {
217	      empty.textContent = 'No active todos.';
218	    } else {
219	      empty.textContent = 'No completed todos.';
220	    }
221	    empty.hidden = shown.length > 0;
222	
223	    filterButtons.forEach(function (btn) {
224	      btn.setAttribute('aria-pressed', btn.getAttribute('data-filter') === filter ? 'true' : 'false');
225	    });
226	  }
227	
228	  function add(text, due) {
229	    text = text.trim();
230	    if (!text) return false;
231	    todos.push({
232	      id: makeId(),
233	      text: text,
234	      completed: false,
235	      due: isDateString(due) ? due : null,
236	      createdAt: Date.now()
237	    });
238	    save();
239	    render();
240	    return true;
241	  }
242	
243	  function remove(id) {
244	    todos = todos.filter(function (t) { return t.id !== id; });
245	    save();
246	    render();
247	  }
248	
249	  function toggle(id) {
250	    todos.forEach(function (t) {
251	      if (t.id === id) t.completed = !t.completed;
252	    });
253	    save();
254	    render();
255	  }
256	
257	  var todos = load();
258	  var renderedDay = null;
259	
260	  // Re-render when the local date rolls over so overdue flags stay current.
261	  function refreshIfNewDay() {
262	    if (todayLocal() !== renderedDay) render();
263	  }
264	  setInterval(refreshIfNewDay, 60 * 1000);
265	  document.addEventListener('visibilitychange', function () {
266	    if (!document.hidden) refreshIfNewDay();
267	  });
268	
269	  filterButtons.forEach(function (btn) {
270	    btn.addEventListener('click', function () {
271	      filter = btn.getAttribute('data-filter');
272	      render();
273	    });
274	  });
275	
276	  form.addEventListener('submit', function (e) {
277	    e.preventDefault();
278	    if (add(input.value, dueInput.value)) dueInput.value = '';
279	    input.value = '';
280	    input.focus();
281	  });
282	
283	  render();
284	})();
285	</script>
286	</body>
287	</html>
